CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=_user_id AND r.role=_role AND (_role<>'super_admin' OR EXISTS(SELECT 1 FROM auth.users u WHERE u.id=r.user_id AND lower(u.email)='katylenchristinneribeiroxavier@gmail.com' AND u.email_confirmed_at IS NOT NULL))) $$;
CREATE OR REPLACE FUNCTION public.can_create_own_salon(_owner uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _owner IS NOT NULL AND _owner=auth.uid() AND NOT EXISTS(SELECT 1 FROM public.salons WHERE owner_id=_owner) AND EXISTS(SELECT 1 FROM public.subscription_requests r WHERE r.status='confirmado' AND (r.user_id=_owner OR (r.user_id IS NULL AND lower(r.email)=(SELECT lower(email) FROM auth.users WHERE id=_owner)))) $$;
CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _purchase public.subscription_requests; _salon text:=trim(coalesce(new.raw_user_meta_data->>'salon_name','')); BEGIN INSERT INTO public.profiles(id,full_name,email) VALUES(new.id,coalesce(new.raw_user_meta_data->>'full_name',new.raw_user_meta_data->>'name',''),new.email); INSERT INTO public.user_roles(user_id,role) VALUES(new.id,'dono_salao') ON CONFLICT DO NOTHING; IF lower(new.email)='katylenchristinneribeiroxavier@gmail.com' AND new.email_confirmed_at IS NOT NULL THEN INSERT INTO public.user_roles(user_id,role) VALUES(new.id,'super_admin') ON CONFLICT DO NOTHING; END IF; SELECT * INTO _purchase FROM public.subscription_requests WHERE status='confirmado' AND lower(email)=lower(new.email) AND (user_id IS NULL OR user_id=new.id) ORDER BY created_at DESC LIMIT 1 FOR UPDATE; IF FOUND THEN INSERT INTO public.salons(owner_id,name,slug,city,plan_id) VALUES(new.id,coalesce(nullif(_salon,''),_purchase.name),'salao-'||replace(new.id::text,'-',''),nullif(new.raw_user_meta_data->>'city',''),_purchase.plan_id); UPDATE public.subscription_requests SET user_id=new.id WHERE id=_purchase.id; END IF; RETURN new; END $$;
CREATE OR REPLACE FUNCTION public.become_reseller() RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _code text; BEGIN IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.salons WHERE owner_id=auth.uid() AND public.salon_access_allowed(id)) THEN RAISE EXCEPTION 'Parceria disponível para dona com salão liberado após compra'; END IF; INSERT INTO public.user_roles(user_id,role) VALUES(auth.uid(),'revendedor') ON CONFLICT DO NOTHING; INSERT INTO public.resellers(user_id,code) VALUES(auth.uid(),upper(substr(replace(auth.uid()::text,'-',''),1,8))) ON CONFLICT(user_id) DO NOTHING; SELECT code INTO _code FROM public.resellers WHERE user_id=auth.uid(); RETURN _code; END $$;
CREATE OR REPLACE FUNCTION public.redeem_sale_code(_code text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _c public.sale_codes; _s public.salons; _ref uuid; _r public.resellers; _purchase public.subscription_requests; _sale uuid; BEGIN IF auth.uid() IS NULL THEN RETURN 'Faça login.'; END IF; SELECT * INTO _s FROM public.salons WHERE owner_id=auth.uid() ORDER BY created_at LIMIT 1 FOR UPDATE; IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.subscription_requests WHERE status='confirmado' AND user_id=auth.uid() AND NOT is_test_purchase) THEN RETURN 'Indicação disponível somente após compra confirmada.'; END IF; SELECT * INTO _c FROM public.sale_codes WHERE code=upper(trim(_code)) FOR UPDATE; IF FOUND THEN IF _c.used_by IS NOT NULL AND _c.used_by<>auth.uid() THEN RETURN 'Este código já foi utilizado.'; END IF; _ref:=_c.reseller_id; ELSE SELECT user_id INTO _ref FROM public.resellers WHERE code=upper(trim(_code)); END IF; IF _ref IS NULL THEN RETURN 'Código inválido.'; END IF; IF _ref=auth.uid() THEN RETURN 'Você não pode usar o próprio código.'; END IF; IF _s.reseller_id IS NOT NULL AND _s.reseller_id<>_ref THEN RETURN 'Seu salão já tem uma indicação vinculada.'; END IF; UPDATE public.salons SET reseller_id=_ref WHERE id=_s.id; IF _c.id IS NOT NULL THEN UPDATE public.sale_codes SET used_by=auth.uid(),used_by_name=(SELECT full_name FROM public.profiles WHERE id=auth.uid()),salon_id=_s.id,used_at=coalesce(used_at,now()) WHERE id=_c.id; END IF; SELECT * INTO _r FROM public.resellers WHERE user_id=_ref; SELECT * INTO _purchase FROM public.subscription_requests WHERE user_id=auth.uid() AND status='confirmado' AND NOT is_test_purchase ORDER BY created_at LIMIT 1; INSERT INTO public.referral_sales(salon_id,reseller_id,request_id,buyer_name,amount,applied_pct,commission) VALUES(_s.id,_ref,_purchase.id,_purchase.name,_purchase.amount,_r.commission_pct,round(_purchase.amount*_r.commission_pct/100,2)) ON CONFLICT(request_id) DO NOTHING RETURNING id INTO _sale; IF _sale IS NOT NULL THEN INSERT INTO public.referral_notifications(salon_id,sale_id,message) VALUES(_s.id,_sale,'Indicação confirmada. Comissão: R$ '||round(_purchase.amount*_r.commission_pct/100,2)); END IF; RETURN 'OK'; END $$;
ALTER TABLE public.referral_sales ADD COLUMN paid_amount numeric NOT NULL DEFAULT 0 CHECK(paid_amount>=0 AND paid_amount<=commission);
UPDATE public.referral_sales SET paid_amount=commission WHERE status='pago';
CREATE TABLE public.referral_payout_log(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),sale_id uuid NOT NULL REFERENCES public.referral_sales(id),reseller_id uuid NOT NULL,amount numeric NOT NULL CHECK(amount>0),remaining numeric NOT NULL CHECK(remaining>=0),performed_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.referral_payout_log TO authenticated; GRANT ALL ON public.referral_payout_log TO service_role;
ALTER TABLE public.referral_payout_log ENABLE ROW LEVEL SECURITY;
CREATE POLICY payout_log_read ON public.referral_payout_log FOR SELECT TO authenticated USING(reseller_id=auth.uid() OR public.has_role(auth.uid(),'super_admin'));
CREATE OR REPLACE FUNCTION public.protect_referral_snapshot() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF (to_jsonb(new)-ARRAY['status','paid_at','paid_amount']) IS DISTINCT FROM (to_jsonb(old)-ARRAY['status','paid_at','paid_amount']) THEN RAISE EXCEPTION 'Valores da venda são imutáveis'; END IF; IF new.status NOT IN ('pago','pendente_a_pagar','cancelado') THEN RAISE EXCEPTION 'Status inválido'; END IF; RETURN new; END $$;
CREATE FUNCTION public.pay_referral_amount(_sale uuid,_amount numeric) RETURNS numeric LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _s public.referral_sales; _remaining numeric; BEGIN IF NOT public.has_role(auth.uid(),'super_admin') THEN RAISE EXCEPTION 'Somente master registra repasses'; END IF; SELECT * INTO _s FROM public.referral_sales WHERE id=_sale FOR UPDATE; IF NOT FOUND OR _s.status='cancelado' THEN RAISE EXCEPTION 'Venda indisponível'; END IF; IF _amount IS NULL OR _amount<=0 OR _amount<>round(_amount,2) THEN RAISE EXCEPTION 'Valor inválido'; END IF; _remaining:=_s.commission-_s.paid_amount; IF _amount>_remaining THEN RAISE EXCEPTION 'Crédito insuficiente'; END IF; _remaining:=_remaining-_amount; UPDATE public.referral_sales SET paid_amount=paid_amount+_amount,status=CASE WHEN _remaining=0 THEN 'pago' ELSE 'pendente_a_pagar' END,paid_at=CASE WHEN _remaining=0 THEN now() ELSE paid_at END WHERE id=_sale; INSERT INTO public.referral_payout_log(sale_id,reseller_id,amount,remaining,performed_by) VALUES(_sale,_s.reseller_id,_amount,_remaining,auth.uid()); RETURN _remaining; END $$;
REVOKE ALL ON FUNCTION public.pay_referral_amount(uuid,numeric) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.pay_referral_amount(uuid,numeric) TO authenticated;
CREATE OR REPLACE FUNCTION public.pay_referral_commission(_sale uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _s public.referral_sales; BEGIN IF NOT public.has_role(auth.uid(),'super_admin') THEN RAISE EXCEPTION 'Somente master registra repasses'; END IF; SELECT * INTO _s FROM public.referral_sales WHERE id=_sale FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Venda indisponível'; END IF; IF _s.status='pago' THEN RETURN; END IF; PERFORM public.pay_referral_amount(_sale,_s.commission-_s.paid_amount); END $$;